begin;
select set_config('request.jwt.claims','{}',true);select set_config('request.jwt.claim.sub','',true);select plan(38);
insert into public.tenants(id,shop_name)values('99600000-0000-4000-8000-000000000001','Sales Credit Test');
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('99600000-0000-4000-8000-000000000099','authenticated','authenticated','sales-credit@example.invalid','',now(),'{}',jsonb_build_object('account_type','public_store_customer','customer_tenant_id','99600000-0000-4000-8000-000000000001'),now(),now());
insert into public.user_profiles(user_id,tenant_id,role)values('99600000-0000-4000-8000-000000000099','99600000-0000-4000-8000-000000000001','admin');update auth.users set raw_user_meta_data=raw_user_meta_data||jsonb_build_object('tenant_id','99600000-0000-4000-8000-000000000001')where id='99600000-0000-4000-8000-000000000099';
select set_config('request.jwt.claims',jsonb_build_object('sub','99600000-0000-4000-8000-000000000099','role','authenticated')::text,true);select set_config('request.jwt.claim.sub','99600000-0000-4000-8000-000000000099',true);
insert into public.products(id,tenant_id,name,sku,price,cost,product_type,is_service,track_stock,inventory_qty,stock_quantity,min_stock_level,max_stock_level)values('99600000-0000-4000-8000-000000000002','99600000-0000-4000-8000-000000000001','Credit Sale Product','SALE-CREDIT',1190,1000,'product',false,true,10,10,0,100);
insert into public.sales_invoices(id,tenant_id,invoice_number,customer_name,status,subtotal,net_amount,iva_amount,total,balance,tax_treatment,items)values('99600000-0000-4000-8000-000000000003','99600000-0000-4000-8000-000000000001','FV-CREDIT-001','Credit Customer','draft',4000,4000,760,4760,4760,'tax_included','[{"line_id":"sales-credit-line","product_id":"99600000-0000-4000-8000-000000000002","product_name":"Credit Sale Product","product_sku":"SALE-CREDIT","quantity":4,"unit_price":1000,"price":1000,"discount":0,"cost":1000,"is_service":false}]');
update public.sales_invoices set status='confirmed'where id='99600000-0000-4000-8000-000000000003';
insert into public.sales_payments(tenant_id,invoice_id,payment_method_id,idempotency_key,amount,tax_treatment,net_amount,iva_amount,date)
select '99600000-0000-4000-8000-000000000001','99600000-0000-4000-8000-000000000003',id,'sales-credit-payment',4760,'tax_included',4000,760,now()from public.payment_methods where tenant_id='99600000-0000-4000-8000-000000000001'order by created_at limit 1;
select is((select inventory_qty from public.products where id='99600000-0000-4000-8000-000000000002'),6,'posted sale consumed inventory');
select is((select status from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),'paid','fixture sale is fully paid');
select throws_ok($$select public.create_sales_credit_note('99600000-0000-4000-8000-000000000003','[{"line_index":0,"credited_quantity":1}]',now(),'adjustment','Disabled','credit-disabled')$$,'P0001','Sales credit note workflow is not active for this tenant','sales credit disabled by default');
select is((select count(*)::integer from public.sales_credit_notes),0,'disabled credit leaves no document');
insert into public.sales_return_control_settings(tenant_id,control_mode,activated_at,activated_by)values('99600000-0000-4000-8000-000000000001','enforce',now(),'99600000-0000-4000-8000-000000000099');
insert into public.sales_credit_note_control_settings(tenant_id,control_mode,activated_at,activated_by)values('99600000-0000-4000-8000-000000000001','enforce',now(),'99600000-0000-4000-8000-000000000099');
insert into public.sales_invoices(id,tenant_id,invoice_number,customer_name,status,subtotal,net_amount,iva_amount,total,balance,tax_treatment,items)values('99600000-0000-4000-8000-000000000004','99600000-0000-4000-8000-000000000001','FV-CREDIT-SENT','Credit Customer','sent',1000,1000,0,1000,1000,'no_tax','[{"line_id":"sales-credit-sent-line","product_id":"99600000-0000-4000-8000-000000000002","product_name":"Credit Sale Product","product_sku":"SALE-CREDIT","quantity":1,"unit_price":1000,"price":1000,"discount":0,"cost":1000,"is_service":false}]');
select throws_ok($$select public.create_sales_credit_note('99600000-0000-4000-8000-000000000004','[{"line_index":0,"credited_quantity":1}]',now(),'adjustment','Too early','credit-sent')$$,'P0001','Sales invoice must be confirmed before a credit note','sent invoice cannot receive a credit note');
select is((select count(*)::integer from public.sales_credit_notes),0,'blocked sent credit leaves no evidence rows');
create temp table physical_return on commit drop as select public.create_sales_return('99600000-0000-4000-8000-000000000003','[{"line_index":0,"returned_quantity":2,"disposition":"restock"}]',now(),'Customer return',null,'sales-credit-return')payload;
select is((select inventory_qty from public.products where id='99600000-0000-4000-8000-000000000002'),8,'physical return restocks independently');
create temp table linked_credit on commit drop as select public.create_sales_credit_note('99600000-0000-4000-8000-000000000003',jsonb_build_array(jsonb_build_object('line_index',0,'credited_quantity',2,'disposition','sales_return','sales_return_line_id',(select id from public.sales_return_lines where sales_return_id=((select payload->>'sales_return_id'from physical_return)::uuid)))),now(),'goods_return','Returned goods','linked-sales-credit')payload;
select is((select phase_contract from public.professional_correction_trace_contract_view where operation_id=((select payload->>'operation_id' from linked_credit)::uuid)),(select expected_phase_contract from public.professional_correction_trace_contract_view where operation_id=((select payload->>'operation_id' from linked_credit)::uuid)),'sales credit note has the full ordered trace contract');
select is((select total_amount from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid)),2380::numeric,'return-linked credit stores exact total');
select is((select net_amount from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid)),2000::numeric,'credit reverses exact revenue');
select is((select tax_amount from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid)),380::numeric,'credit reverses exact sales tax');
select is((select cost_amount from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid)),0::numeric,'financial credit does not duplicate the physical return COGS reversal');
select is((select official_dte_status from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid)),'internal','internal credit does not claim DTE issuance');
select ok(exists(select 1 from public.journal_entries where id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and total_debit=2380 and total_credit=2380),'sales credit journal balances revenue, tax, and receivable reversal only');
select is((select debit_amount from public.journal_lines where entry_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and account_code='4100'),2000::numeric,'credit debits revenue');
select is((select debit_amount from public.journal_lines where entry_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and account_code='2150'),380::numeric,'credit debits IVA liability');
select is((select credit_amount from public.journal_lines where entry_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and account_code='1130'),2380::numeric,'credit credits receivable');
select is((select count(*)::integer from public.journal_lines where entry_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and account_code='1105'),0,'sales credit does not duplicate inventory value posted by the physical return');
select is((select count(*)::integer from public.journal_lines where entry_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and account_code='5100'),0,'sales credit does not duplicate COGS reversal posted by the physical return');
select is((select count(*)::integer from public.stock_movements where operation_id=((select payload->>'operation_id'from linked_credit)::uuid)),0,'credit note never moves physical stock');
select is((select inventory_qty from public.products where id='99600000-0000-4000-8000-000000000002'),8,'credit does not restock twice');
select is((select credited_amount from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),2380::numeric,'invoice stores credited total');
select is((select customer_credit_balance from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),2380::numeric,'paid invoice exposes customer credit balance');
select is((select paid_amount from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),4760::numeric,'credit never changes collected payment');
select ok((public.create_sales_credit_note('99600000-0000-4000-8000-000000000003','[{"line_index":0,"credited_quantity":2}]',now(),'retry','Retry','linked-sales-credit')->>'replayed')::boolean,'sales credit is idempotent');
select throws_ok(format('select public.void_sales_return(%L::uuid,%L,%L)',(select payload->>'sales_return_id'from physical_return),'Blocked','return-blocked-credit'),'P0001','Void linked sales credit notes before voiding this sales return','posted credit protects linked physical return');
select throws_ok($$update public.sales_invoices set total=5000 where id='99600000-0000-4000-8000-000000000003'$$,'P0001','Void posted sales credit notes before editing invoice financial lines','posted credit freezes source invoice');
create temp table financial_credit on commit drop as select public.create_sales_credit_note('99600000-0000-4000-8000-000000000003','[{"line_index":0,"credited_quantity":1,"disposition":"financial_only"}]',now(),'price_adjustment','Price adjustment','financial-sales-credit')payload;
select is((select cost_amount from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from financial_credit)::uuid)),0::numeric,'financial-only credit does not reverse COGS');
select is((select customer_credit_balance from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),3570::numeric,'second credit increases customer credit balance');
select throws_ok($$select public.create_sales_credit_note('99600000-0000-4000-8000-000000000003','[{"line_index":0,"credited_quantity":2}]',now(),'over','Over','over-sales-credit')$$,'P0001','Sales credit quantity exceeds original line balance','cumulative over-credit is blocked');
create temp table linked_void on commit drop as select public.void_sales_credit_note((select(payload->>'sales_credit_note_id')::uuid from linked_credit),'Correction','void-linked-sales-credit')payload;
select is((select phase_contract from public.professional_correction_trace_contract_view where operation_id=((select payload->>'operation_id' from linked_void)::uuid)),(select expected_phase_contract from public.professional_correction_trace_contract_view where operation_id=((select payload->>'operation_id' from linked_void)::uuid)),'sales credit-note void has the full ordered trace contract');
select is((select credited_amount from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),1190::numeric,'credit void recalculates invoice credited total');
select ok(exists(select 1 from public.journal_entries where id=(select void_journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and reversal_of_id=(select journal_entry_id from public.sales_credit_notes where id=((select payload->>'sales_credit_note_id'from linked_credit)::uuid))and total_debit=total_credit),'credit void appends linked balanced reversal');
select lives_ok(format('select public.void_sales_return(%L::uuid,%L,%L)',(select payload->>'sales_return_id'from physical_return),'Credit voided','void-return-after-credit'),'physical return can void after linked credit void');
select is((select inventory_qty from public.products where id='99600000-0000-4000-8000-000000000002'),6,'return void removes prior restock');
update public.sales_credit_notes set official_dte_status='issued'where id=((select payload->>'sales_credit_note_id'from financial_credit)::uuid);
select throws_ok(format('select public.void_sales_credit_note(%L::uuid,%L,%L)',(select payload->>'sales_credit_note_id'from financial_credit),'Internal void','issued-sales-credit-void'),'P0001','Issued tax credit notes require an official reversal document','issued sales DTE cannot use internal void');
update public.sales_credit_notes set official_dte_status='internal'where id=((select payload->>'sales_credit_note_id'from financial_credit)::uuid);select public.void_sales_credit_note((select(payload->>'sales_credit_note_id')::uuid from financial_credit),'Correction','void-financial-sales-credit');
select is((select credited_amount from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),0::numeric,'voiding all credits clears credited amount');
select is((select customer_credit_balance from public.sales_invoices where id='99600000-0000-4000-8000-000000000003'),0::numeric,'voiding all credits clears customer credit balance');
select * from finish();rollback;
